// ── Utilities ────────────────────────────────────────────────────────────────
function normalizeDomain(raw) {
  if (!raw) return '';
  var s = String(raw).trim().toLowerCase();
  s = s.replace(/^https?:\/\//, '').replace(/^www\./, '');
  return s.split('/')[0].split('?')[0].split('#')[0];
}

// ── DataforSEO ───────────────────────────────────────────────────────────────
var API_BASE = 'https://api.dataforseo.com/v3';
var API_KEY  = Buffer.from('abhishekbolarshetty@gmail.com:6aa69ca0a4bf8188').toString('base64');
var AUTH_HDR = 'Basic ' + API_KEY;

async function dfsPost(endpoint, body) {
  try {
    var result = await this.helpers.httpRequest({
      method:  'POST',
      url:     API_BASE + endpoint,
      headers: { 'Authorization': AUTH_HDR, 'Content-Type': 'application/json' },
      body:    JSON.stringify(body),
      returnFullResponse: false,
      ignoreHttpStatusErrors: true
    });
    return typeof result === 'string' ? JSON.parse(result) : result;
  } catch (e) {
    return { _error: e.message, tasks: [] };
  }
}

// ── Top-level try/catch ensures Respond node always gets valid JSON ──────────
try {

// Parse input — n8n webhook v2 wraps POST body under .body
var rawInput = $input.first().json;
var input    = (rawInput.body && typeof rawInput.body === 'object') ? rawInput.body : rawInput;

// Ping mode for the dashboard's "Test" button
if (input.ping === true) {
  return [{ json: { success: true, ping: 'ok', service: 'order-tracker' } }];
}

var target     = normalizeDomain(input.target || '');
var rootDomain = normalizeDomain(input.root_domain || '');

if (!target || !rootDomain) {
  return [{ json: {
    success: false,
    error: 'Both `target` (your domain) and `root_domain` (publisher domain) are required.',
    debug_received: rawInput
  } }];
}

// Build DataforSEO request — find backlinks pointing TO `target` FROM `rootDomain`
// Match the root domain itself + any subdomain (blog., www., etc.)
var dfsBody = [{
  target: target,
  limit: 1000,
  mode: 'as_is',
  backlinks_status_type: 'live',
  include_subdomains: true,
  include_indirect_links: true,
  exclude_internal_backlinks: true,
  filters: [
    ['domain_from', '=', rootDomain],
    'or',
    ['domain_from', 'like', '%.' + rootDomain]
  ],
  order_by: ['rank,desc']
}];

var resp = await dfsPost.call(this, '/backlinks/backlinks/live', dfsBody);

if (resp._error) {
  return [{ json: {
    success: false,
    root_domain: rootDomain,
    error: 'DataforSEO request failed: ' + resp._error
  } }];
}

var task = resp && resp.tasks && resp.tasks[0];
if (!task) {
  return [{ json: {
    success: false,
    root_domain: rootDomain,
    error: 'No task in DataforSEO response',
    raw: resp
  } }];
}

if (task.status_code && task.status_code !== 20000) {
  return [{ json: {
    success: false,
    root_domain: rootDomain,
    error: 'DataforSEO error ' + task.status_code + ': ' + (task.status_message || 'unknown'),
    cost: resp.cost || 0
  } }];
}

var r0    = task.result && task.result[0];
var items = (r0 && r0.items) || [];
var total = (r0 && typeof r0.total_count === 'number') ? r0.total_count : items.length;

// Map DataforSEO items → frontend shape
var links = items.map(function(it) {
  return {
    page_url:    it.url_from   || '',
    domain_from: it.domain_from || '',
    anchor:      (it.anchor || '').slice(0, 200),
    follow:      it.dofollow !== false,           // dofollow boolean → follow
    is_lost:     !!it.is_lost,
    first_seen:  it.first_seen || '',
    last_seen:   it.last_seen  || '',
    page_rank:   typeof it.rank === 'number' ? it.rank : null,
    text_pre:    (it.text_pre || '').slice(0, 200)
  };
}).filter(function(l) { return !l.is_lost; });   // only keep currently live links

return [{ json: {
  success:     true,
  root_domain: rootDomain,
  target:      target,
  total_found: links.length,
  total_in_index: total,
  cost:        resp.cost || 0,
  links:       links
} }];

} catch (topErr) {
  return [{ json: {
    success: false,
    error:   String(topErr),
    stack:   topErr && topErr.stack ? topErr.stack.slice(0, 800) : ''
  } }];
}
